import { Hono, type Context } from "hono";
import { AppError } from "../lib/errors";
import { consultarStock } from "../lib/stock";
import { dataUrlDesdeBase64, identificarPiezaConVision, imagenDesdeArchivo, modeloGroqVision } from "../lib/pieza-ia";

type AppEnv = { Bindings: Env };

export const analizarRoutes = new Hono<AppEnv>();

function asFile(value: unknown): File | null {
  if (!value || typeof value === "string") return null;
  if (value instanceof File) return value;
  if (value instanceof Blob) {
    const named = value as Blob & { name?: string };
    return new File([value], named.name || "pieza.jpg", { type: value.type || "image/jpeg" });
  }
  return null;
}

async function extraerImagen(c: Context<AppEnv>): Promise<string> {
  const contentType = (c.req.header("Content-Type") ?? "").toLowerCase();

  if (contentType.includes("application/json")) {
    const body = await c.req.json<{
      image?: string;
      imagen?: string;
      image_base64?: string;
      mimeType?: string;
    }>();
    const raw = body.image || body.imagen || body.image_base64 || "";
    if (!raw.trim()) {
      throw new AppError(400, "Falta la imagen en base64 (campo image, imagen o image_base64).", "IMAGE_REQUIRED");
    }
    return dataUrlDesdeBase64(raw, body.mimeType || "image/jpeg");
  }

  if (contentType.includes("multipart/form-data")) {
    let body: Record<string, string | File>;
    try {
      body = (await c.req.parseBody()) as Record<string, string | File>;
    } catch {
      throw new AppError(400, "No se pudo leer el formulario. Verifica el archivo de imagen.", "INVALID_MULTIPART");
    }
    const file =
      asFile(body.image) ??
      asFile(body.imagen) ??
      asFile(body.file) ??
      asFile(body.foto) ??
      asFile(body.archivo);
    if (file) {
      const imagen = await imagenDesdeArchivo(file);
      return imagen.dataUrl;
    }
    const raw = [body.image, body.imagen, body.image_base64].find((value) => typeof value === "string" && value.trim()) as
      | string
      | undefined;
    if (raw) return dataUrlDesdeBase64(raw);
    throw new AppError(400, "Falta la imagen. Usa el campo 'image' o 'file'.", "IMAGE_REQUIRED");
  }

  throw new AppError(400, "Envía la imagen como JSON (base64) o multipart/form-data.", "INVALID_CONTENT_TYPE");
}

analizarRoutes.post("/", async (c) => {
  const dataUrl = await extraerImagen(c);
  const pieza = await identificarPiezaConVision(c.env, dataUrl);
  const stock = consultarStock(pieza);

  return c.json({
    ok: true,
    modelo: modeloGroqVision(c.env),
    pieza: {
      nombre: pieza.nombre,
      material: pieza.material,
      medida: pieza.medida,
      categoria: pieza.categoria,
      observaciones: pieza.observaciones,
      confianza: pieza.confianza,
      palabras_clave: pieza.palabras_clave,
    },
    stock,
  });
});
